#include <cstdio>
#include <fcntl.h>
#include <iostream>
#include <sys/stat.h>
#include <unistd.h>
#include <cstddef>
#include <sys/mman.h>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " <file>\n";
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) {
        std::perror("open");
        return 1;
    }

    struct stat info{};
    if (fstat(fd, &info) == -1) {
        std::perror("fstat");
        close(fd);
        return 1;
    }

    std::cout << "size=" << info.st_size << '\n';
    if (info.st_size < 3) {
    std::cerr << "this step requires at least 3 bytes\n";
    close(fd);
    return 1;
}

std::size_t length = static_cast<std::size_t>(info.st_size);
void* mapping = mmap(nullptr, length, PROT_READ, MAP_PRIVATE, fd, 0);
if (mapping == MAP_FAILED) {
    std::perror("mmap");
    close(fd);
    return 1;
}

const unsigned char* bytes =
    static_cast<const unsigned char*>(mapping);

std::cout << "third=" << static_cast<char>(bytes[2]) << '\n';

if (munmap(mapping, length) == -1) {
    std::perror("munmap");
    close(fd);
    return 1;
}

    if (close(fd) == -1) {
        std::perror("close");
        return 1;
    }
    return 0;
}
